<?php
namespace VPM\Booking;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class DB {
    public static function table( string $name ): string { global $wpdb; return $wpdb->prefix . 'vpm_booking_' . $name; }
    public static function install(): void {
        require_once ABSPATH . 'wp-admin/includes/upgrade.php'; global $wpdb; $charset = $wpdb->get_charset_collate();
        $schemas = array(
            'operation_locks' => 'booking_id bigint unsigned NOT NULL, lease varchar(64) NOT NULL, expires_at bigint NOT NULL, PRIMARY KEY  (booking_id)',
            'product_templates' => 'id varchar(50) NOT NULL, partner_id bigint unsigned NOT NULL, payload longtext NOT NULL, PRIMARY KEY  (id), KEY partner_id (partner_id)',
            'memberships' => 'partner_id bigint unsigned NOT NULL, user_id bigint unsigned NOT NULL, role varchar(20) NOT NULL, created_at bigint NOT NULL, PRIMARY KEY  (partner_id,user_id), KEY user_id (user_id)',
            'connections' => 'partner_id bigint unsigned NOT NULL, mode varchar(20) NOT NULL, adapter varchar(50) NOT NULL, credentials longtext NOT NULL, last_error varchar(50) NOT NULL DEFAULT \'\', assistance tinyint unsigned NOT NULL DEFAULT 0, updated_at bigint NOT NULL, PRIMARY KEY  (partner_id)',
            'rates' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, partner_id bigint unsigned NOT NULL, product_id varchar(50) NOT NULL, price_cents bigint unsigned NOT NULL, pricing varchar(20) NOT NULL, capacity int unsigned NOT NULL, enabled tinyint unsigned NOT NULL DEFAULT 0, PRIMARY KEY  (id), UNIQUE KEY partner_product (partner_id,product_id)',
            'allocations' => 'booking_id bigint unsigned NOT NULL, rate_id bigint unsigned NOT NULL, starts_at bigint NOT NULL, ends_at bigint NOT NULL, expires_at bigint NOT NULL, state varchar(20) NOT NULL, PRIMARY KEY  (booking_id), KEY occupancy (rate_id,state,starts_at,ends_at)',
            'fulfilment' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, booking_id bigint unsigned NOT NULL, action varchar(20) NOT NULL, result longtext DEFAULT NULL, status varchar(20) NOT NULL, attempts int unsigned NOT NULL DEFAULT 0, next_attempt bigint NOT NULL DEFAULT 0, locked_until bigint NOT NULL DEFAULT 0, locked_by varchar(64) NOT NULL DEFAULT \'\', error_code varchar(50) NOT NULL DEFAULT \'\', created_at bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY booking_action (booking_id,action)',
            'demo' => 'booking_id bigint unsigned NOT NULL, state varchar(30) NOT NULL, created_at bigint NOT NULL, PRIMARY KEY  (booking_id)',
            'loyalty' => 'contact_id bigint unsigned NOT NULL, coupon_id bigint unsigned NOT NULL, booking_id bigint unsigned NOT NULL, issued_at bigint NOT NULL, PRIMARY KEY  (contact_id), UNIQUE KEY coupon_id (coupon_id)',
            'audit' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, actor_id bigint unsigned NOT NULL, action varchar(50) NOT NULL, object_type varchar(30) NOT NULL, object_id bigint unsigned NOT NULL, created_at bigint NOT NULL, PRIMARY KEY  (id), KEY object_ref (object_type,object_id)',
            'access' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, booking_id bigint unsigned NOT NULL, token_hash varchar(64) NOT NULL, expires_at bigint NOT NULL, revoked_at bigint NOT NULL DEFAULT 0, PRIMARY KEY  (id), UNIQUE KEY token_hash (token_hash), KEY booking_id (booking_id)',
            'changes' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, booking_id bigint unsigned NOT NULL, kind varchar(20) NOT NULL, state varchar(20) NOT NULL, created_at bigint NOT NULL, reviewed_at bigint NOT NULL DEFAULT 0, PRIMARY KEY  (id), UNIQUE KEY booking_kind (booking_id,kind)',
            'quotes' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, public_id varchar(36) NOT NULL, partner_id bigint unsigned NOT NULL, base_cents bigint unsigned NOT NULL, context longtext NOT NULL, details longtext DEFAULT NULL, terms text NOT NULL, expires_at bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY public_id (public_id), KEY expiry (expires_at)',
            'partners' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, airport varchar(3) NOT NULL, name varchar(180) NOT NULL, stripe_account varchar(80) NOT NULL, commission_bps int unsigned NOT NULL, active tinyint unsigned NOT NULL DEFAULT 1, PRIMARY KEY  (id)',
            'coupons' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, code varchar(40) NOT NULL, kind varchar(10) NOT NULL, customer_hash varchar(64) NOT NULL DEFAULT \'\', value int unsigned NOT NULL, max_uses int unsigned NOT NULL, max_per_customer int unsigned NOT NULL DEFAULT 1, budget_cents bigint unsigned NOT NULL, used_uses int unsigned NOT NULL DEFAULT 0, held_uses int unsigned NOT NULL DEFAULT 0, used_cents bigint unsigned NOT NULL DEFAULT 0, held_cents bigint unsigned NOT NULL DEFAULT 0, starts_at bigint NOT NULL, ends_at bigint NOT NULL, airport varchar(3) NOT NULL DEFAULT \'\', partner_id bigint unsigned NOT NULL DEFAULT 0, PRIMARY KEY  (id), UNIQUE KEY code (code)',
            'bookings' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, public_id varchar(36) NOT NULL, request_key varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, request_hash varchar(64) NOT NULL, partner_id bigint unsigned NOT NULL, customer_email varchar(254) NOT NULL, locale varchar(5) NOT NULL, snapshot longtext NOT NULL, state varchar(30) NOT NULL, payment_state varchar(30) NOT NULL, stripe_session varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT \'\', stripe_pi varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT \'\', refunded_cents bigint unsigned NOT NULL DEFAULT 0, created_at bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY public_id (public_id), UNIQUE KEY request_key (request_key), UNIQUE KEY stripe_session_unique (stripe_session)',
            'coupon_uses' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, coupon_id bigint unsigned NOT NULL, booking_id bigint unsigned NOT NULL, customer_hash varchar(64) NOT NULL, amount_cents bigint unsigned NOT NULL, state varchar(15) NOT NULL, PRIMARY KEY  (id), UNIQUE KEY booking_id (booking_id), KEY customer_coupon (coupon_id,customer_hash)',
            'ledger' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, booking_id bigint unsigned NOT NULL, entry_key varchar(150) NOT NULL, account varchar(40) NOT NULL, cents bigint NOT NULL, currency varchar(3) NOT NULL, created_at bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY entry_key (entry_key), KEY booking_id (booking_id)',
            'refunds' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, public_id varchar(36) NOT NULL, booking_id bigint unsigned NOT NULL, request_key varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, cents bigint unsigned NOT NULL, status varchar(20) NOT NULL, stripe_refund varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT \'\', attempts int unsigned NOT NULL DEFAULT 0, next_attempt bigint NOT NULL DEFAULT 0, error_code varchar(80) NOT NULL DEFAULT \'\', PRIMARY KEY  (id), UNIQUE KEY public_id (public_id), UNIQUE KEY booking_request (booking_id,request_key)',
            'events' => 'event_id varchar(150) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, source varchar(20) NOT NULL, created_at bigint NOT NULL, PRIMARY KEY  (event_id)',
            'outbox' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, event_key varchar(150) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, topic varchar(80) NOT NULL, purpose varchar(20) NOT NULL, contact_id bigint unsigned NOT NULL DEFAULT 0, payload longtext NOT NULL, status varchar(20) NOT NULL DEFAULT \'pending\', attempts int unsigned NOT NULL DEFAULT 0, next_attempt bigint NOT NULL DEFAULT 0, locked_until bigint NOT NULL DEFAULT 0, locked_by varchar(64) NOT NULL DEFAULT \'\', error_code varchar(80) NOT NULL DEFAULT \'\', created_at bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY event_key (event_key), KEY dispatch (status,next_attempt)',
            'contacts' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, email varchar(254) NOT NULL, state varchar(20) NOT NULL, consent_version varchar(80) NOT NULL, consent_hash varchar(64) NOT NULL, consent_text text NOT NULL, revision bigint unsigned NOT NULL DEFAULT 1, unsubscribe_payload text NOT NULL, requested_at bigint NOT NULL, confirmed_at bigint NOT NULL DEFAULT 0, revoked_at bigint NOT NULL DEFAULT 0, token_hash varchar(64) NOT NULL, expires_at bigint NOT NULL, unsubscribe_hash varchar(64) NOT NULL, PRIMARY KEY  (id), UNIQUE KEY email (email), UNIQUE KEY token_hash (token_hash), UNIQUE KEY unsubscribe_hash (unsubscribe_hash)',
            'consent_log' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, contact_id bigint unsigned NOT NULL, action varchar(20) NOT NULL, consent_version varchar(80) NOT NULL, consent_hash varchar(64) NOT NULL, consent_text text NOT NULL, revision bigint unsigned NOT NULL, created_at bigint NOT NULL, PRIMARY KEY  (id), KEY contact_id (contact_id)',
            'documents' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, booking_id bigint unsigned NOT NULL, reference varchar(100) NOT NULL, kind varchar(20) NOT NULL, url text NOT NULL, created_at bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY reference (reference)',
            'deliveries' => 'id bigint unsigned NOT NULL AUTO_INCREMENT, event_id varchar(150) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, outgoing_event varchar(150) NOT NULL, state varchar(30) NOT NULL, created_at bigint NOT NULL, PRIMARY KEY  (id), UNIQUE KEY event_id (event_id)',
            'rate_limits' => 'bucket varchar(100) NOT NULL, hits int unsigned NOT NULL, expires_at bigint NOT NULL, PRIMARY KEY  (bucket)',
        );
        // A nullable Stripe session allows several bookings before Checkout is created.
        $schemas['bookings'] = str_replace( "stripe_session varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT ''", 'stripe_session varchar(100) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL', $schemas['bookings'] );
        foreach ( $schemas as $name => $body ) { $body = str_replace( ', ', ",\n", $body ); dbDelta( 'CREATE TABLE ' . self::table( $name ) . " ($body) ENGINE=InnoDB $charset;" ); }
        foreach ( array_keys( $schemas ) as $name ) { $status = $wpdb->get_row( $wpdb->prepare( 'SHOW TABLE STATUS WHERE Name = %s', self::table( $name ) ), ARRAY_A ); Config::require( $status && strcasecmp( $status['Engine'], 'InnoDB' ) === 0, 'transactional_schema_required' ); }
        Config::require( PHP_INT_SIZE >= 8 && function_exists( 'openssl_encrypt' ) && function_exists( 'openssl_decrypt' ), 'openssl_and_64bit_php_required' );
        update_option( 'vpm_booking_db_version', 6, false );
        if ( ! wp_next_scheduled( 'vpm_booking_worker' ) ) { wp_schedule_event( time() + 300, 'vpm_booking_five_minutes', 'vpm_booking_worker' ); }
    }
    public static function query( string $sql ): int { global $wpdb; $r = $wpdb->query( $sql ); if ( false === $r ) { throw new \RuntimeException( 'database_operation_failed' ); } return (int) $r; }
    public static function insert( string $table, array $data ): int { global $wpdb; if ( false === $wpdb->insert( self::table( $table ), $data ) ) { throw new \RuntimeException( 'database_insert_failed' ); } return (int) $wpdb->insert_id; }
    public static function update( string $table, array $data, array $where ): void { global $wpdb; if ( false === $wpdb->update( self::table( $table ), $data, $where ) ) { throw new \RuntimeException( 'database_update_failed' ); } }
    private static int $depth = 0;
    public static function tx( callable $fn ) {
        $level = self::$depth; $savepoint = 'vpm_sp_' . $level; self::query( $level ? 'SAVEPOINT ' . $savepoint : 'START TRANSACTION' ); ++self::$depth;
        try { $result = $fn(); self::query( $level ? 'RELEASE SAVEPOINT ' . $savepoint : 'COMMIT' ); return $result; }
        catch ( \Throwable $e ) { self::query( $level ? 'ROLLBACK TO SAVEPOINT ' . $savepoint : 'ROLLBACK' ); throw $e; }
        finally { --self::$depth; }
    }
    public static function row( string $table, string $field, $value, bool $lock = false ): array { global $wpdb; $allowed = array( 'id', 'public_id', 'request_key', 'code', 'email', 'token_hash', 'unsubscribe_hash', 'reference' ); if ( ! in_array( $field, $allowed, true ) ) { throw new \RuntimeException( 'invalid_lookup' ); } return (array) $wpdb->get_row( $wpdb->prepare( 'SELECT * FROM ' . self::table( $table ) . " WHERE $field = %s" . ( $lock ? ' FOR UPDATE' : '' ), $value ), ARRAY_A ); }
}
final class Config {
    public static function secret( string $name ): string { $v = defined( $name ) ? constant( $name ) : getenv( $name ); return is_string( $v ) ? $v : ''; }
    public static function require( bool $test, string $code ): void { if ( ! $test ) { throw new \RuntimeException( $code ); } }
    public static function integer( $value, int $min, int $max = 100000000 ): int { self::require( is_int( $value ) && $value >= $min && $value <= $max, 'invalid_integer' ); return $value; }
    public static function key( string $key ): string { self::require( (bool) preg_match( '/^[a-zA-Z0-9_.:-]{8,100}$/D', $key ), 'invalid_idempotency_key' ); return $key; }
    public static function email( string $value ): string { $v = strtolower( trim( $value ) ); self::require( (bool) is_email( $v ), 'invalid_email' ); return $v; }
    public static function seal( array $data ): string { $iv = random_bytes( 12 ); $tag = ''; $encrypted = openssl_encrypt( wp_json_encode( $data ), 'aes-256-gcm', hash( 'sha256', wp_salt( 'secure_auth' ), true ), OPENSSL_RAW_DATA, $iv, $tag ); self::require( false !== $encrypted, 'payload_encryption_failed' ); return base64_encode( $iv . $tag . $encrypted ); }
    public static function open( string $data ): array { $raw = base64_decode( $data, true ); self::require( false !== $raw && strlen( $raw ) >= 28, 'invalid_payload' ); $plain = openssl_decrypt( substr( $raw, 28 ), 'aes-256-gcm', hash( 'sha256', wp_salt( 'secure_auth' ), true ), OPENSSL_RAW_DATA, substr( $raw, 0, 12 ), substr( $raw, 12, 16 ) ); self::require( false !== $plain, 'payload_decryption_failed' ); return (array) json_decode( $plain, true ); }
}
